import{_ as a,o as t,c as n,ak as r}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse(`{"title":"Chainy game design","description":"Current gameplay direction, October 12, 2026. Based on Christian Jude Villaber's technical design and the user's explicit replacement of the earlier plan.","frontmatter":{"title":"Chainy game design","description":"Current gameplay direction, October 12, 2026. Based on Christian Jude Villaber's technical design and the user's explicit replacement of the earlier plan.","source":"docs/game-design.md","category":"Game & system design","sourceUpdated":"2026-10-12T21:55:56+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/game-design.md","filePath":"content/docs/game-design.md"}`),s={name:"content/docs/game-design.md"};function i(o,e,l,d,c,h){return t(),n("div",null,[...e[0]||(e[0]=[r('<div><h1 id="chainy-game-design">Chainy game design<a class="header-anchor" href="#chainy-game-design" aria-label="Link to this section">​</a></h1><p>Current gameplay direction, October 12, 2026. Based on Christian Jude Villaber&#39;s technical design and the user&#39;s explicit replacement of the earlier plan.</p><h2 id="purpose-and-audience">Purpose and audience<a class="header-anchor" href="#purpose-and-audience" aria-label="Link to this section">​</a></h2><p>Chainy introduces foundational Web3, Blockchain and AI concepts through an offline 3D Android game for ages 12–17. Use plain English, visual examples and short explanations. Assume that some players are new to touch controls and the subject matter.</p><p>The game is single-player. Learning about blockchain and AI does not require real cryptocurrency, an online blockchain, or a cloud AI service.</p><h2 id="player-experience">Player experience<a class="header-anchor" href="#player-experience" aria-label="Link to this section">​</a></h2><ol><li>Open the game and create or select a local learner profile.</li><li>Enter a learning level and move through the 3D scene.</li><li>Interact with the lesson or dialogue to learn a concept.</li><li>Start one Quiz, Wordle or BlockMatch activity.</li><li>Read the result and explanation. Retry according to that activity&#39;s rules.</li><li>Save progress, then continue or leave. Returning players load this device&#39;s saved progress.</li></ol><p>The actual level layout, movement controls and lesson sequence must be agreed by Sherwin and Christian. The previous tappable nine-lesson map is no longer the gameplay specification.</p><h2 id="the-three-mini-games">The three mini-games<a class="header-anchor" href="#the-three-mini-games" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Mode</th><th>Established by the technical design</th><th>Rules still to freeze on CH-02</th><th>Completion check</th></tr></thead><tbody><tr><td>Quiz</td><td>Shows questions, evaluates answers and calculates scores; current UI reads ScriptableObjects</td><td>Approved question set, scoring, pass/completion rule, retry handling</td><td>Correct and incorrect answers produce the expected score and explanation; saved result reloads</td></tr><tr><td>Wordle</td><td>Validates guesses and evaluates letters</td><td>Educational word list and definitions, word length, guess limit, repeated-letter feedback, win/loss/retry rule</td><td>Valid/invalid guesses, repeated letters, win and exhausted attempts behave as agreed</td></tr><tr><td>BlockMatch</td><td>Board operations, matches, cascades and objectives; uses pooled objects</td><td>What counts as a match, learner meaning, board limits, move/time rule, no-move case, cascade/end rule</td><td>Legal/illegal moves, cascade completion, win/loss and no-move handling match the agreed rules</td></tr></tbody></table><p>A familiar puzzle format does not by itself teach a concept. Each activity needs a short learning objective and a result explanation. Word guessing may support vocabulary; matching needs a meaningful relation that the learner can explain. Sean drafts and checks the learning material with Sherwin; Christian checks whether the rule can be implemented as described.</p><p>The user confirmed that exact mini-game rules are not yet agreed. No exact score threshold, board size, dictionary, word length, lesson count or attempt limit is approved by the supplied document. Put those values in one short rules sheet before building content around them.</p><h2 id="levels-characters-and-art">Levels, characters and art<a class="header-anchor" href="#levels-characters-and-art" aria-label="Link to this section">​</a></h2><p>Retain the approved friendly rounded 3D style: the blue-haired explorer in yellow, screen-faced robots and compact island scenery. See the <a href="/Chainy-Docs/content/docs/design/design-brief.html">visual brief</a>. The source reports an existing player controller and models; reuse them before commissioning replacements.</p><p>Build a small representative level first. Level count and art quantity follow the measured effort to finish that level. Prior artwork and the old illustrated PDF remain visual/history references; their old mechanics and screen layouts are superseded.</p><h2 id="profiles-results-and-progress">Profiles, results and progress<a class="header-anchor" href="#profiles-results-and-progress" aria-label="Link to this section">​</a></h2><p>A learner code selects a profile stored on that device. It is not an authenticated online account. Switching learners must clear the previous learner&#39;s visible progress before showing the next profile.</p><p>Only one mini-game receives gameplay input at a time. Loading, saving, pause and board resolution must prevent accidental duplicate actions. Show “saved” only after SQLite confirms the write. A save failure offers a retry and must not erase the last good record.</p><p>Christian must settle whether score means latest, best or cumulative score, and whether attempts count guesses, question responses or completed playthroughs. Sean must check that the chosen meaning supports the approved evaluation. See the <a href="/Chainy-Docs/content/docs/design/database-schema.html">data reference</a>.</p><h2 id="ui-and-accessibility">UI and accessibility<a class="header-anchor" href="#ui-and-accessibility" aria-label="Link to this section">​</a></h2><p>Miguel provides profile, menu, in-game instructions, result, pause and save-error screens. Use readable text and generous touch targets. Essential instructions must work with sound off, and feedback must use text or icons as well as color. Show the current objective and available action clearly.</p><p>The <a href="/Chainy-Docs/content/docs/design/app-flow.html">player flow</a> defines navigation and recovery. The <a href="/Chainy-Docs/content/docs/qa-evaluation.html">test checklist</a> defines the evidence needed before beta.</p><h2 id="delivery-and-ownership">Delivery and ownership<a class="header-anchor" href="#delivery-and-ownership" aria-label="Link to this section">​</a></h2><p>Sherwin owns learning-game rules and scope; Christian owns implementation and integration; Luis owns art; Sean owns instructional copy and manuscript; Miguel owns UI and supports documentation/testing.</p><p><strong>Fixed beta: November 3–6. Fixed pre-final: November 21, 2026.</strong> First accepted loop: October 18 planning target. Integrated candidate: October 30 planning target. Testing, manuscript work and rehearsal remain in the <a href="/Chainy-Docs/content/docs/kanban-plan-draft.html">task plan</a>.</p><p>The old record-ordering activity, three-copy simulation, classifier and grid-agent implementation requirements are withdrawn by the user&#39;s October 12 decision. Their archived specifications are not work to add alongside the three new modes.</p></div>',1)])])}const m=a(s,[["render",i]]);export{u as __pageData,m as default};
